import { ArrowLeft, BookOpen, CheckCircle, Circle, ClockCounterClockwise, DotsThreeVertical, EnvelopeSimple, Gear, GitBranch, Globe, House, Lightning, MagnifyingGlass, Minus, Moon, PaperPlaneTilt, Plus, Play, Sparkle, SquaresFour, Sun, UploadSimple, UserCircle, Wrench } from '@phosphor-icons/react';
